  if (esbuildMatch) return esbuildMatch[1];
  const violationMatch = resultText.match(/^\[[A-Z][^\]]*\] [^\n]+/m);
  if (violationMatch) return violationMatch[0];
  const buildErrMatch = resultText.match(/Build errors:\s*\n([^\n]+)/);
